from __future__ import annotations

from dataclasses import dataclass, field

# AutoDrive node flags. Other values may exist in files; they are kept
# unchanged and shown like regular nodes.
REGULAR_FLAG = 0
SUBPRIO_FLAG = 1

# Regular nodes generated by AutoDrive's map scan from the map's traffic
# routes. They behave like regular nodes; the editor keeps the flag
# until the user changes a node's type.
MAP_SCAN_FLAG = 2

KNOWN_FLAGS = (REGULAR_FLAG, SUBPRIO_FLAG, MAP_SCAN_FLAG)


@dataclass
class NodeData:
    """One AutoDrive waypoint. x and z are the map position, y the height. incoming and outgoing
    hold the ids of connected nodes.
    """

    node_id: int
    x: float
    y: float
    z: float
    flag: int = 0

    incoming: set[int] = field(default_factory=set)

    outgoing: set[int] = field(default_factory=set)

    @property
    def is_subprio(self) -> bool:
        return self.flag == SUBPRIO_FLAG

    @property
    def is_regular(self) -> bool:
        """Regular nodes and nodes with an unknown flag."""

        return not self.is_subprio

    @property
    def has_known_flag(self) -> bool:
        return self.flag in KNOWN_FLAGS

    @property
    def is_from_map_scan(self) -> bool:
        return self.flag == MAP_SCAN_FLAG


@dataclass
class MarkerData:
    """A named destination attached to a node."""

    node_id: int
    name: str = ""
    group: str = ""


@dataclass
class MarkerGroup:
    """A marker group. Route files list the groups with an id; savegame
    configs only store group names on the markers, so group_id is None."""

    name: str
    group_id: int | None = None


@dataclass
class AutoDriveData:
    """All nodes and markers of an AutoDrive network, by node id.

    The order of `markers` is kept as in the file: in savegame configs
    the position of a marker is its number, which vehicles use as parking
    destination.
    """

    nodes: dict[int, NodeData] = field(default_factory=dict)

    markers: dict[int, MarkerData] = field(default_factory=dict)

    marker_groups: list[MarkerGroup] = field(default_factory=list)

    def add_node(self, node: NodeData) -> None:
        if node.node_id <= 0:
            raise ValueError("Eine Node-ID muss größer als 0 sein.")

        if node.node_id in self.nodes:
            raise ValueError(f"Die Node-ID {node.node_id} ist bereits vorhanden.")

        self.nodes[node.node_id] = node

    def add_marker(self, marker: MarkerData, position: int | None = None) -> None:
        """Adds a marker at the end, or at the given position in the marker
        order."""

        if marker.node_id not in self.nodes:
            raise ValueError(f"Der Marker verweist auf die unbekannte Node-ID {marker.node_id}.")

        if position is None or position >= len(self.markers):
            self.markers[marker.node_id] = marker
            return

        ordered = list(self.markers.items())
        ordered.insert(position, (marker.node_id, marker))
        self.markers = dict(ordered)

    def remove_marker(self, node_id: int) -> tuple[int, MarkerData]:
        """Removes a node's marker. Returns its former position and the
        marker, so it can be put back in place."""

        position = self.marker_position(node_id)

        if position is None:
            raise ValueError(f"Node {node_id} hat keinen Marker.")

        return position, self.markers.pop(node_id)

    def move_marker(self, from_node_id: int, to_node_id: int) -> None:
        """Attaches a marker to another node. Its position in the marker
        order stays the same."""

        if from_node_id not in self.markers:
            raise ValueError(f"Node {from_node_id} hat keinen Marker.")

        if to_node_id not in self.nodes:
            raise ValueError(f"Die Node-ID {to_node_id} ist nicht vorhanden.")

        if to_node_id in self.markers:
            raise ValueError(f"Node {to_node_id} hat bereits einen Marker.")

        marker = self.markers[from_node_id]
        marker.node_id = to_node_id

        self.markers = {
            (to_node_id if node_id == from_node_id else node_id): existing
            for node_id, existing in self.markers.items()
        }

    def find_marker_group(self, name: str) -> MarkerGroup | None:
        return next((group for group in self.marker_groups if group.name == name), None)

    def marker_group_names(self) -> list[str]:
        """All group names: the group list plus groups only named on
        markers, without duplicates."""

        names = [group.name for group in self.marker_groups]

        for marker in self.markers.values():
            if marker.group not in names:
                names.append(marker.group)

        return names

    def markers_in_group(self, name: str) -> list[MarkerData]:
        return [marker for marker in self.markers.values() if marker.group == name]

    def next_marker_group_id(self) -> int | None:
        """Id for a new group. Groups from savegame configs have no ids;
        then new groups get none either."""

        ids = [group.group_id for group in self.marker_groups if group.group_id is not None]

        return max(ids) + 1 if ids else None

    def marker_position(self, node_id: int) -> int | None:
        """Position of a node's marker in the marker order."""

        for position, marker_node_id in enumerate(self.markers):
            if marker_node_id == node_id:
                return position

        return None

    def get_node(self, node_id: int) -> NodeData | None:
        return self.nodes.get(node_id)

    def get_marker(self, node_id: int) -> MarkerData | None:
        return self.markers.get(node_id)

    def get_sorted_nodes(self) -> list[NodeData]:
        return [self.nodes[node_id] for node_id in sorted(self.nodes)]

    def validate_connections(self) -> list[str]:
        errors = []

        for node in self.nodes.values():
            for target_id in node.outgoing:
                if target_id not in self.nodes:
                    errors.append(
                        f"Node {node.node_id} besitzt eine "
                        f"ausgehende Verbindung zur unbekannten "
                        f"Node {target_id}."
                    )

            for source_id in node.incoming:
                if source_id not in self.nodes:
                    errors.append(
                        f"Node {node.node_id} besitzt eine "
                        f"eingehende Verbindung von der unbekannten "
                        f"Node {source_id}."
                    )

        return errors

    def clear(self) -> None:
        self.nodes.clear()
        self.markers.clear()
        self.marker_groups.clear()

    def __len__(self) -> int:
        return len(self.nodes)
